import SwiftUI

/// The three home screen icons. Dark is the primary icon (the dark close-up white panda); Blue
/// and Red Panda are the alternate icons generated by make-assets.sh and declared in
/// project-base.yml (ASSETCATALOG_COMPILER_ALTERNATE_APP_ICON_NAMES).
enum QenoAppIcon: String, CaseIterable, Identifiable {
    case dark, blue, red

    var id: String { rawValue }

    /// The name in the picker.
    var name: String {
        switch self {
        case .dark: String(localized: "Dark")
        case .blue: String(localized: "Blue")
        case .red: String(localized: "Red Panda")
        }
    }

    /// The name passed to setAlternateIconName; nil is the primary (Dark) icon.
    var alternateIconName: String? {
        switch self {
        case .dark: nil
        case .blue: "AppIcon-Blue"
        case .red: "AppIcon-Red"
        }
    }

    /// The icon iOS is showing now; nil (no alternate icon) means the primary (Dark) icon.
    static var current: QenoAppIcon {
        switch UIApplication.shared.alternateIconName {
        case "AppIcon-Blue": .blue
        case "AppIcon-Red": .red
        default: .dark
        }
    }

    /// The icon's background colour, for the preview thumbnail.
    var background: Color {
        switch self {
        case .dark: .black
        case .blue: Site.blue
        case .red: Color(red: 0.78, green: 0.30, blue: 0.10)
        }
    }

    /// The panda face for the preview: the red panda for the red icon, the white panda for both
    /// the dark and the blue icon (both are the white panda, on different backgrounds).
    var face: QenoCharacter { self == .red ? .red : .white }
}

/// The app icon picker: Dark, Blue, Red Panda, a checkmark on the one in use. Picking one
/// switches the home screen icon only; it does not change the selected character. Reached from
/// the Qeno details page, next to Character.
struct AppIconPickerView: View {
    @State private var current = QenoAppIcon.current

    var body: some View {
        List {
            Section {
                ForEach(QenoAppIcon.allCases) { icon in
                    Button {
                        current = icon
                        UIApplication.shared.setAlternateIconName(icon.alternateIconName) { error in
                            if error != nil { current = QenoAppIcon.current }
                        }
                    } label: {
                        HStack(spacing: 12) {
                            preview(for: icon, size: 44)
                            Text(icon.name)
                            Spacer()
                            if current == icon {
                                Image(systemName: "checkmark").foregroundStyle(Site.blue)
                            }
                        }
                    }
                    .buttonStyle(.plain)
                }
            } footer: {
                Text("The icon on the home screen. Picking a character also switches the icon to match, when that character has one.")
            }
        }
        .navigationTitle("App Icon")
        .navigationBarTitleDisplayMode(.inline)
        .onAppear { current = QenoAppIcon.current }
    }

    /// A mini app-icon preview: the icon's background colour with the panda's face on it.
    private func preview(for icon: QenoAppIcon, size: CGFloat) -> some View {
        ZStack {
            RoundedRectangle(cornerRadius: size * 0.22, style: .continuous).fill(icon.background)
            CharacterFace(character: icon.face, size: size * 0.72)
        }
        .frame(width: size, height: size)
        .accessibilityHidden(true)
    }
}
